def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 3:
        return 'C'
    if n >= 100:
        return 'D' if history[-1][1] == 'C' else 'C'
    opp_c = sum(1 for _, o in history if o == 'C')
    my_c = sum(1 for m, _ in history if m == 'C')
    last_opp = history[-1][1]
    opp_d_rate = (n - opp_c) / n
    if n >= 20 and opp_d_rate > 0.6:
        if my_c > opp_c + 5:
            return 'D'
        return 'C'
    if n >= 10:
        window = history[-10:]
        w_opp_c = sum(1 for _, o in window if o == 'C')
        if w_opp_c <= 2:
            return 'D'
        if w_opp_c >= 9:
            return 'C'
    if last_opp == 'D':
        d_count = 0
        for m, o in reversed(history):
            if o == 'D':
                d_count += 1
            else:
                break
        if d_count >= 3:
            return 'D'
        if d_count == 1:
            return 'C' if rng.random() < 0.3 else 'D'
        return 'D'
    if n >= 5:
        last5 = history[-5:]
        opp_defections = sum(1 for _, o in last5 if o == 'D')
        if opp_defections == 0:
            return 'C'
        if opp_defections >= 2:
            return 'D'
    return 'C'
